-- A planet's map generation settings, made from the terrain kit (lib/kit.lua). Works in both stages: the loader
-- (prototypes/build.lua) and the designer preview (script/designer) call the same function, so the preview is
-- generated by exactly the rules the finished planet will use.
--
-- `L` is a lookup that knows what exists in this game (data.raw while loading, `prototypes` at runtime):
--   L.tile(name)                 -> {autoplace = bool, color = {r, g, b}, fluid = bool} or nil
--   L.tile_home(name)            -> the vanilla planet a natural tile comes from, or nil
--   L.reference_colors           -> {planet = {r, g, b}} (see prototypes/kit.lua)
--   L.resource(name)             -> {fluid = bool, autoplace = bool} or nil
--   L.entity(name)               -> true if an autoplaceable entity of that name exists
--   L.cliff(name)                -> true if that cliff exists
--   L.decoratives(planet)        -> the decoratives a vanilla planet places (that exist)
--   L.pollutant(name)            -> true if that airborne pollutant exists
--   L.style_entities(kind, style)-> existing, autoplaceable entities of a PLANTS / ROCKS style
--   L.ore_entity(key)            -> the entity that stands for the planet's own ore `key`
-- `problem(key, ...)` records a problem (see locale [planet-workshop-problem]).

local catalog = require("__planet-workshop__.lib.catalog")
local kit = require("__planet-workshop__.lib.kit")

local M = {}

--- Returns {mgs = MapGenSettings, picture, sky, starting = {{entity, fluid, richness}}, pollutant, territory}.
function M.build(p, L, problem)
  local t = p.terrain
  local mgs = {
    property_expression_names = {},
    autoplace_controls = {
      water = {frequency = 1, size = t.liquid_amount, richness = 1},
      [kit.control("patch")] = {frequency = 1, size = t.patch_size, richness = 1},
      [kit.control("plants")] = {frequency = 1, size = math.max(t.plants.amount, 0.01), richness = 1},
      [kit.control("rocks")] = {frequency = 1, size = math.max(t.rocks.amount, 0.01), richness = 1},
    },
    -- only what is listed generates (some tiles, like Aquilo's rough ice, would otherwise turn up by default)
    autoplace_settings = {
      tile = {treat_missing_as_default = false, settings = {}},
      decorative = {treat_missing_as_default = false, settings = {}},
      entity = {treat_missing_as_default = false, settings = {}},
    },
  }
  local props, controls = mgs.property_expression_names, mgs.autoplace_controls
  local tiles, decoratives, entities = mgs.autoplace_settings.tile.settings, mgs.autoplace_settings.decorative.settings,
    mgs.autoplace_settings.entity.settings
  local out = {mgs = mgs, starting = {}}

  -- Land shape
  local shape = catalog.SHAPES[t.shape]
  if shape.vanilla then
    props.elevation = shape.vanilla
  else
    props.elevation = kit.elevation_expression(t.shape, t.liquid == "water")
    props.cliff_elevation = "cliff_elevation_from_elevation"
    props.cliffiness = "cliffiness_basic"
  end

  -- Liquid
  local liquid = catalog.LIQUIDS[t.liquid]
  local liquid_tiles = {}
  if liquid.shallow then
    local deep = (liquid.deep_below or -2) <= -8 and "liquid_deep_8" or "liquid_deep_2"
    for depth, expr in pairs{shallow = "liquid_shallow", deep = deep} do
      local name = liquid[depth]
      if L.tile(name) then
        tiles[name] = {}
        liquid_tiles[name] = true
        props["tile:" .. name .. ":probability"] = kit.X .. expr
      else
        problem("missing", name, "liquid")
      end
    end
    if liquid.fish and L.entity("fish") then entities.fish = {} end
  end

  -- Ground: each tile in its own slot; the slot's control holds the tile's share / the average share
  local ground = {}
  for _, g in ipairs(t.ground) do
    local tile = L.tile(g.tile)
    if not tile then
      problem("missing", g.tile, "ground")
    elseif not tile.autoplace then
      problem("cant-generate", g.tile)
    elseif not liquid_tiles[g.tile] and #ground < kit.GROUND_SLOTS then
      ground[#ground + 1] = g
    end
  end
  if #ground == 0 then
    problem("no-ground")
    for _, name in ipairs{"sand-1", "red-desert-0", "dirt-4"} do
      if L.tile(name) then ground[#ground + 1] = {tile = name, share = 1} end
    end
  end
  local share_total = 0
  for _, g in ipairs(ground) do share_total = share_total + g.share end
  for i, g in ipairs(ground) do
    tiles[g.tile] = {}
    props["tile:" .. g.tile .. ":probability"] = kit.ground_expression(i)
    controls[kit.ground_control(i)] = {frequency = 1, size = g.share / (share_total / #ground), richness = 1}
  end

  -- Look: picture and sky
  local colors, by_home = {}, {}
  for _, g in ipairs(ground) do
    local tile = L.tile(g.tile)
    colors[#colors + 1] = {color = tile and tile.color or {0.5, 0.5, 0.5}, weight = g.share / share_total}
    local home = L.tile_home(g.tile) or "other" -- modded tiles: no home planet, colour decides
    by_home[home] = (by_home[home] or 0) + g.share
  end
  if liquid.shallow and L.tile(liquid.shallow) then
    colors[#colors + 1] = {color = L.tile(liquid.shallow).color or {0.2, 0.3, 0.4},
      weight = 0.35 * math.min(1, math.sqrt(t.liquid_amount))}
  end
  local picture = p.look.picture
  if picture == "auto" then -- the home planet of half or more of the ground, else the closest colour
    for home, share in pairs(by_home) do
      if share >= share_total / 2 and L.reference_colors[home] then picture = home end
    end
  end
  if picture == "auto" then
    picture = catalog.closest_picture(catalog.average_color(colors), L.reference_colors)
  end
  out.picture = picture
  local sky = p.look.sky
  if sky == "auto" then -- the home planet of most of the ground
    sky = "nauvis"
    local best = 0
    for _, home in ipairs(catalog.PLANETS) do
      if (by_home[home] or 0) > best then sky, best = home, by_home[home] end
    end
  end
  out.sky = sky

  -- Cliffs
  local cliff = catalog.CLIFFS[t.cliffs.style]
  if cliff and not L.cliff(cliff) then
    problem("missing", cliff, "cliffs")
    cliff = nil
  end
  mgs.cliff_settings = {
    name = cliff or "cliff", control = "", cliff_elevation_0 = 10, cliff_elevation_interval = 40, cliff_smoothing = 0,
    richness = cliff and t.cliffs.amount or 0,
  }

  -- Plants and rocks
  for kind, choice in pairs{PLANTS = t.plants, ROCKS = t.rocks} do
    if choice.amount > 0 then
      for _, style in ipairs(choice.styles) do
        local expr = kind == "PLANTS" and kit.plants_expression(style) or kit.rocks_expression(style)
        for _, name in ipairs(L.style_entities(kind, style)) do
          entities[name] = {}
          props["entity:" .. name .. ":probability"] = expr
        end
      end
    end
  end

  -- Decorations: those of each ground tile's home planet
  if t.decorations then
    for home in pairs(by_home) do
      for _, name in ipairs(L.decoratives(home)) do decoratives[name] = {} end
    end
  end

  -- Enemies
  local enemy = catalog.ENEMIES[p.enemies.kind]
  out.pollutant = enemy.pollutant and L.pollutant(enemy.pollutant) and enemy.pollutant or nil
  for _, name in ipairs(enemy.entities or {}) do
    if L.entity(name) then entities[name] = {} else problem("missing", name, "enemies") end
  end
  for _, control in ipairs{enemy.control, table.unpack(enemy.controls or {})} do
    controls[control] = {frequency = p.enemies.amount, size = p.enemies.amount, richness = 1}
  end
  if p.enemies.kind == "pentapods" then
    if entities["gleba-spawner"] then props["entity:gleba-spawner:probability"] = kit.X .. "gleba_spawner" end
    if entities["gleba-spawner-small"] then
      props["entity:gleba-spawner-small:probability"] = kit.X .. "gleba_spawner_small"
    end
  end
  if enemy.territory then
    local units = {}
    for _, name in ipairs(enemy.territory) do
      if L.entity(name) then units[#units + 1] = name end
    end
    if #units > 0 then
      out.territory = {
        units = units,
        territory_index_expression = kit.territory_expression(kit.territory_index(p.enemies.amount)),
        territory_variation_expression = "demolisher_variation_expression",
        minimum_territory_size = 10,
      }
      mgs.territory_settings = out.territory
    else
      problem("missing", "demolishers", "enemies")
    end
  end

  -- Resources: each takes the next free slot of its kind
  local used, seen = {}, {}
  for _, res in ipairs(p.resources) do
    local entity
    if res.resource:sub(1, 5) == "@ore:" then
      entity = p.ore_keys[res.resource:sub(6)] and L.ore_entity(res.resource:sub(6))
      if not entity then problem("missing", res.resource, "resources") end
    elseif res.resource:sub(1, 1) ~= "@" and L.resource(res.resource) then
      entity = res.resource
      if not L.resource(entity).autoplace then
        problem("cant-generate", entity)
        entity = nil
      end
    else
      problem("missing", res.resource, "resources")
    end
    if entity and not seen[entity] then
      seen[entity] = true
      local info = L.resource(entity) or {fluid = false}
      local starting = res.starting == "yes" or (res.starting == "default" and not info.fluid)
      local slots
      for _, s in ipairs(kit.RESOURCE_SLOTS) do
        if s.fluid == info.fluid and s.starting == starting then slots = s end
      end
      used[slots.key] = (used[slots.key] or 0) + 1
      local i = used[slots.key]
      if i > slots.count then
        problem("too-many-resources", entity)
      else
        -- patch size follows the resource's usual density (iron is denser than stone)
        local defaults = catalog.RESOURCE_DEFAULTS[entity]
        local density = (defaults and defaults.base_density or 8) / 8
        if info.fluid then density = 1 end
        props["entity:" .. entity .. ":probability"] = kit.resource_expression(slots.key, i, "probability")
        props["entity:" .. entity .. ":richness"] = kit.resource_expression(slots.key, i, "richness")
        entities[entity] = {}
        controls[kit.resource_control(slots.key, i)] = {frequency = res.frequency, size = res.size * density,
          richness = res.richness}
        if starting then
          out.starting[#out.starting + 1] = {entity = entity, fluid = info.fluid, richness = res.richness}
        end
      end
    end
  end

  return out
end

return M
